// Generated 2026-11-15 to match TankWorldIndia's CATEGORY_TREE exactly (source of truth for supplier
// categories: same slugs, names, parents and order) plus TankBazaar's facility categories.
// 439 nodes: TWI 21 L1 · 230 L2 · 178 L3; TankBazaar 4 L1 · 6 L2.
// TankBazaar part mirrors the TankBazaar app: facilityClass storage|process (L1 Storage Terminals /
// Process Industries), processType slugs as Process Industries L2, plus Oil Rigs & Platforms and
// Pipelines for TankBazaar's rig and pipeline datasets. Captive/independent, port/inland/floating,
// rig type and pipeline commodity are attributes in TankBazaar, not categories.
// Retired slugs and where they now point: CATEGORY_REDIRECTS below.
// Master company-category tree. Doc id === slug (stable, cross-app join key).
// Seed via Admin → Companies tab → "Seed master tree" (handleSeedCategories).

export interface CategorySeedNode {
  id: string;        // === slug; used as the Firestore document id
  slug: string;
  name: string;
  level: 1 | 2 | 3;
  parentId: string;  // "" for level 1; parent slug for level 2 and 3
  order: number;
  // Which feeder app this category tree belongs to. Added after the tree turned out to
  // already be structurally split: storage-terminals, process-industries, and
  // natural-resources-and-upstream (Refineries, Terminals, Fertilisers, Gas Processing,
  // Oil & Gas Exploration, etc.) are TankBazaar's asset/facility classifications; everything
  // else is TWI's supplier/equipment/service taxonomy. Every node inherits its source from
  // its level-1 root. No TankBazaar company data has been seeded yet -- this tags the
  // existing placeholder branches ahead of that, so the two taxonomies are never ambiguous
  // once TankBazaar data starts flowing in.
  source: "TWI" | "TankBazaar";
}

